package org.marketreview.nativeapp;
import java.util.*;
public final class VwapChecks {
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static void near(double a,double b){check(Double.isFinite(a)&&Math.abs(a-b)<1e-10,"formula mismatch");}interface Work{void run();}static void refuses(Work w){boolean bad=false;try{w.run();}catch(Exception e){bad=true;}check(bad,"expected refusal");}
 static Vwap.Point point(long time,String date,double close,double volume,double amount){Vwap.Point p=new Vwap.Point();p.time=time;p.session=date;p.close=close;p.high=close+2;p.low=close-1;p.volume=volume;p.amount=amount;return p;}
 public static void run(){Vwap.Params p=new Vwap.Params();p.volumeUnit="lots";List<Vwap.Point> rows=new ArrayList<>(Arrays.asList(point(1,"2000-01-01",10,1,Double.NaN),point(2,"2000-01-01",20,3,Double.NaN)));Vwap.Series old=Vwap.calculate(rows,p);near(old.values[1],17.5);check(old.approximate&&old.label.contains("收盘价"),"legacy not HLC3");p.mode="hlc3-approx";near(Vwap.calculate(rows,p).values[1],17.5+1.0/3);p.mode="actual-amount";p.volumeToShares=100;p.amountToCny=10000;p.priceBasis="unadjusted";rows.get(0).amount=.1;rows.get(1).amount=.6;near(Vwap.calculate(rows,p).values[1],17.5);p.volumeToShares=Double.NaN;check(!Double.isFinite(Vwap.calculate(rows,p).values[0]),"no guessed scale");p.volumeToShares=100;p.priceBasis="adjusted";check(!Double.isFinite(Vwap.calculate(rows,p).values[0]),"qfq incomparable");p.priceBasis="unadjusted";rows.get(0).amount=Double.NaN;check(!Double.isFinite(Vwap.calculate(rows,p).values[1]),"no missing amount fallback/skip");rows.get(0).amount=.1;Vwap.Series prefix=Vwap.calculate(rows,p);rows.add(point(3,"2000-01-02",30,2,.6));Vwap.Series actual=Vwap.calculate(rows,p);near(actual.values[2],30);check(actual.breakBefore[2],"day reset");for(int i=0;i<2;i++)near(prefix.values[i],actual.values[i]);rows.add(point(4,"2000-01-02",1000,100,1000));Vwap.Series future=Vwap.calculate(rows,p);for(int i=0;i<3;i++)near(actual.values[i],future.values[i]);rows.remove(3);Vwap.Point lunch=point(2,"2000-01-01",0,Double.NaN,Double.NaN);lunch.axisGap=true;Vwap.Series noon=Vwap.calculate(Arrays.asList(rows.get(0),lunch,point(3,"2000-01-01",20,3,.6)),p);check(!Double.isFinite(noon.values[1])&&noon.breakBefore[2],"no axis compression/fill");near(noon.values[2],17.5);p.quantities="cumulative";near(Vwap.calculate(Arrays.asList(point(1,"2000-01-01",10,1,.1),point(2,"2000-01-01",15,4,.7)),p).values[1],17.5);Vwap.Series recover=Vwap.calculate(Arrays.asList(point(1,"2000-01-01",10,1,Double.NaN),point(2,"2000-01-01",15,4,.7)),p);check(!Double.isFinite(recover.values[0]),"no future repair");near(recover.values[1],17.5);Vwap.Series reset=Vwap.calculate(Arrays.asList(point(1,"2000-01-01",10,4,.7),point(2,"2000-01-01",10,1,.1),point(3,"2000-01-01",10,8,1.4)),p);check(!Double.isFinite(reset.values[1])&&!Double.isFinite(reset.values[2]),"counter reset refuses");p.quantities="incremental";p.period="week";refuses(()->Vwap.calculate(rows,p));p.anchor="loaded-window";refuses(()->Vwap.calculate(rows,p));p.anchorId="actual-loaded-fixture-start";near(Vwap.calculate(rows,p).values[2],13000.0/600);p.mode="legacy-close-approx";p.period="intraday";p.anchor="session";Vwap.Series zero=Vwap.calculate(Arrays.asList(point(1,"2000-01-01",10,0,Double.NaN),point(2,"2000-01-01",10,1,Double.NaN),point(3,"2000-01-01",20,0,Double.NaN)),p);check(!Double.isFinite(zero.values[0]),"zero denominator missing");near(zero.values[2],10);}
 public static void main(String[] args){run();System.out.println("PASS VWAP production Java old-close/HLC3/actual units/session/window/cumulative/gaps/causal/null; pure staging only");}
}
